async def act(page):
    """
    Navigate to the Sales > Orders page, export the Orders grid as CSV using the
    page's Export controls, aggregate cancelled orders per-customer email, and
    print the email,name,phone of the customer with the most cancellations as a
    single comma-separated line.

    This continues from the current UI state (we're on the Customers page) and
    attempts to dismiss any modal/popup that might block interaction before
    navigating to Orders.
    """
    import re
    import csv
    import io
    import os
    import tempfile
    import asyncio

    # Defensive: try to dismiss an obvious popup overlay that may be blocking
    # the page (there is a test popup visible in the current UI state).
    try:
        # Try common close button labels (×, x, Close)
        close_btns = page.get_by_role("button", name=re.compile(r"^(×|x|close)$", re.IGNORECASE))
        if await close_btns.count() > 0:
            await close_btns.first.click()
        else:
            # Try any button that contains the word 'close'
            contains_close = page.get_by_role("button", name=re.compile(r"close", re.IGNORECASE))
            if await contains_close.count() > 0:
                await contains_close.first.click()
    except Exception:
        # Best-effort only; continue even if dismissal fails
        pass

    # Also send Escape to dismiss overlays
    try:
        await page.keyboard.press("Escape")
        await asyncio.sleep(0.25)
    except Exception:
        pass

    # Navigate to the Orders management page (relative path)
    await page.goto('/index.php/admin/sales_order/')
    # small pause to allow the UI to render
    await asyncio.sleep(0.8)

    # Scope: try to find the export controls cell whose accessible name contains 'Export to'
    export_cell = page.get_by_role("cell", name=re.compile(r"Export\s*to", re.IGNORECASE))
    if await export_cell.count() == 0:
        # fallback: scan all cells and pick the one whose visible text contains 'Export to'
        cells = page.get_by_role("cell")
        found = False
        for i in range(await cells.count()):
            c = cells.nth(i)
            try:
                txt = (await c.inner_text()) or ""
            except Exception:
                txt = ""
            if re.search(r"Export\s*to", txt or "", re.IGNORECASE):
                export_cell = c
                found = True
                break
        if not found:
            raise RuntimeError("Could not find Export controls on Orders page")

    # Within the export cell, prefer a native combobox (<select>) and choose CSV
    comb_count = await export_cell.get_by_role("combobox").count()
    if comb_count > 0:
        comb = export_cell.get_by_role("combobox").first
        # Try selecting by visible label 'CSV'
        try:
            await comb.select_option(label="CSV")
        except Exception:
            # fallback: examine options and select the one whose label contains 'CSV'
            try:
                opts = comb.get_by_role("option")
                nopts = await opts.count()
                chosen = False
                for j in range(nopts):
                    opt_txt = (await opts.nth(j).inner_text() or "").strip()
                    if re.search(r"\bCSV\b", opt_txt, re.IGNORECASE):
                        await comb.select_option(label=opt_txt)
                        chosen = True
                        break
                if not chosen:
                    # try selecting by option value containing 'csv'
                    for j in range(nopts):
                        val = await opts.nth(j).get_attribute('value')
                        if val and 'csv' in val.lower():
                            await comb.select_option(value=val)
                            chosen = True
                            break
            except Exception:
                # If we cannot explicitly set CSV, continue; default may already be CSV
                pass
    else:
        # fallback: select first page-level combobox if present
        all_combs = page.get_by_role("combobox")
        if await all_combs.count() > 0:
            try:
                await all_combs.first.select_option(label="CSV")
            except Exception:
                pass

    # Find the Export button scoped to the export_cell
    export_btns = export_cell.get_by_role("button", name=re.compile(r"Export", re.IGNORECASE))
    if await export_btns.count() > 0:
        export_btn = export_btns.first
    else:
        # Fallback to any page-level Export button
        page_export = page.get_by_role("button", name=re.compile(r"Export", re.IGNORECASE))
        if await page_export.count() == 0:
            raise RuntimeError("Export button not found on Orders page")
        export_btn = page_export.first

    # Trigger the export and capture the download
    tmpfile = os.path.join(tempfile.gettempdir(), 'magento_orders_export.csv')
    try:
        async with page.expect_download() as dd:
            await export_btn.click()
        download = await dd.value
        await download.save_as(tmpfile)
    except Exception:
        # Try force click if normal click failed (overlay may be blocking)
        try:
            async with page.expect_download() as dd:
                await export_btn.click(force=True)
            download = await dd.value
            await download.save_as(tmpfile)
        except Exception as exc:
            raise RuntimeError(f"Failed to trigger or capture orders export download: {exc}")

    # Read and decode the CSV text (utf-8 primary, latin-1 fallback)
    with open(tmpfile, 'rb') as fh:
        b = fh.read()
    try:
        csv_text = b.decode('utf-8')
    except Exception:
        csv_text = b.decode('latin-1')

    # Normalize newlines for csv module
    csv_text = csv_text.replace('\r\n', '\n').replace('\r', '\n')

    # Parse CSV
    reader = csv.DictReader(io.StringIO(csv_text))
    headers = reader.fieldnames or []

    # Identify likely columns for status, email, billing name, phone
    status_col = None
    email_col = None
    name_col = None
    phone_col = None
    for h in headers:
        if not h:
            continue
        hl = h.lower()
        if status_col is None and 'status' in hl:
            status_col = h
        if email_col is None and 'email' in hl:
            email_col = h
        if name_col is None and ('billing' in hl and 'name' in hl or hl.strip() == 'name' or 'customer' in hl and 'name' in hl):
            name_col = h
        if phone_col is None and ('telephone' in hl or 'phone' in hl):
            phone_col = h

    # Conservative fallbacks for required columns
    if email_col is None:
        for h in headers:
            if h and 'email' in h.lower():
                email_col = h
                break
    if status_col is None:
        for h in headers:
            if h and 'stat' in h.lower():
                status_col = h
                break

    if email_col is None or status_col is None:
        raise RuntimeError(f"Could not locate required columns in orders export. Headers: {headers}")

    # Aggregate cancelled orders per email
    cancelled_counts = {}
    sample_info = {}  # email -> (name, phone)
    for row in reader:
        status = (row.get(status_col) or '').strip()
        if not status:
            continue
        if re.search(r'cancel', status, re.IGNORECASE):
            email = (row.get(email_col) or '').strip()
            if not email:
                # find any email-like column
                for h in headers:
                    if h and 'email' in h.lower():
                        email = (row.get(h) or '').strip()
                        if email:
                            break
            if not email:
                continue
            cancelled_counts[email] = cancelled_counts.get(email, 0) + 1
            if email not in sample_info:
                # sample a name
                name = ''
                if name_col:
                    name = (row.get(name_col) or '').strip()
                if not name:
                    for h in headers:
                        if h and 'name' in h.lower():
                            v = (row.get(h) or '').strip()
                            if v:
                                name = v
                                break
                # sample a phone
                phone = ''
                if phone_col:
                    phone = (row.get(phone_col) or '').strip()
                if not phone:
                    for h in headers:
                        if h and ('telephone' in h.lower() or 'phone' in h.lower()):
                            v = (row.get(h) or '').strip()
                            if v:
                                phone = v
                                break
                sample_info[email] = (name, phone)

    if not cancelled_counts:
        raise RuntimeError('No cancelled orders found in orders export')

    # Determine the email with the maximum cancellations
    max_email = None
    max_count = -1
    for em, cnt in cancelled_counts.items():
        if cnt > max_count:
            max_count = cnt
            max_email = em

    if not max_email:
        raise RuntimeError('Could not determine customer with most cancellations')

    name, phone = sample_info.get(max_email, ('', ''))

    # Print exactly the requested triple: email,name,phone
    print(f"{max_email},{name},{phone}")

